mapper.select:
SELECT hra.auth_id, hra.resident_id, b.building_name, h.unit_no, h.house_number, r.name, r.id_card, r.phone, hra.type, hra.auth_material_url, hra.audit_status, hra.audit_remark, a.username AS admin_username, hra.create_time FROM house_resident_auth hra LEFT JOIN house h ON hra.house_id = h.house_id LEFT JOIN building b ON h.building_id = b.building_id LEFT JOIN resident r ON hra.resident_id = r.resident_id LEFT JOIN admin a ON hra.admin_id = a.admin_id
AND hra.audit_status = #{query.auditStatus}
AND h.building_id = #{query.buildingId}
AND h.unit_no = #{query.unitNo}
AND h.house_number = #{query.houseNumber}
AND (r.name LIKE CONCAT('%', #{query.keyword}, '%') OR r.id_card LIKE CONCAT('%', #{query.keyword}, '%') OR r.phone LIKE CONCAT('%', #{query.keyword}, '%') OR hra.audit_remark LIKE CONCAT('%', #{query.keyword}, '%'))
AND hra.create_time >= #{query.startDate}
AND hra.create_time <= #{query.endDate}
ORDER BY hra.create_time DESC

