mapper.select:
SELECT h.house_id, b.building_name, h.unit_no, h.house_number, COUNT(hra.auth_id) AS auth_count FROM house h LEFT JOIN building b ON h.building_id = b.building_id LEFT JOIN house_resident_auth hra ON h.house_id = hra.house_id WHERE h.house_id IN
#{houseId}
GROUP BY h.house_id, b.building_name, h.unit_no, h.house_number

SELECT r.resident_id, r.name, r.phone, GROUP_CONCAT(DISTINCT CONCAT(b.building_name, '-', h.unit_no, '单元-', h.house_number) SEPARATOR ', ') AS house_name, COUNT(hra.auth_id) AS auth_count FROM resident r LEFT JOIN house_resident_auth hra ON r.resident_id = hra.resident_id LEFT JOIN house h ON hra.house_id = h.house_id LEFT JOIN building b ON h.building_id = b.building_id WHERE r.resident_id IN
#{residentId}
GROUP BY r.resident_id, r.name, r.phone
